# Generated by `shiny theme new` from shiny-gradient.png
# Base scheme: Catppuccin Macchiato — https://github.com/mbadolato/iTerm2-Color-Schemes (via Ghostty)
# Edit freely; `shiny theme set <name>` re-applies.
THEME_BASE="Catppuccin Macchiato"
GHOSTTY_THEME="Catppuccin Macchiato"   # built-in: ghostty +list-themes
ACCENT_PRESET=4                    # macOS accent: -1 graphite 0 red 1 orange 2 yellow 3 green 4 blue 5 purple 6 pink
WALLPAPER="wallpaper.jpg"

BG="#24273A"         # window background
BG_DARK="#1E2030"    # frames, omnibox
SURFACE="#363A4F"    # borders, dividers, inactive window border
SELECTION="#494D64"  # selected rows, text selection
MUTED="#5B6078"      # shortcuts, scrollbar
COMMENT="#8087A2"    # subtext, inactive tabs
FG="#CAD3F5"         # primary text
FG_DIM="#B8C0E0"     # secondary text
ACCENT="#8AADF4"     # primary accent: focus border, icons, links, text highlight, icon tint
ACCENT2="#F5A97F"    # secondary accent: cursor, shortcuts, search selection
